import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {historicalCatalog as catalog} from './helpers/fast-hands-split-entries-catalog.mjs';
const read=p=>fs.readFileSync(new URL('../'+p,import.meta.url),'utf8');
test('previous games stay in correct shelves after sprint and javelin admission',()=>{assert.deepEqual(catalog.games.map(g=>g.id),['long-jump','hurdles','high-jump','pole-vault','shot-put','discus','sprint-100m','javelin']);assert.deepEqual(catalog.minigames.map(g=>g.id),['reaction-rod','beer-slide','tower-climb','fast-hands']);for(const id of ['shot-put','discus','tower-climb']){const entry=[...catalog.games,...catalog.minigames].find(g=>g.id===id);assert.equal(entry.href,`/games/${id}/`);assert.equal(entry.imageStyle,'illustration');assert.ok(fs.existsSync(new URL('../public'+entry.image,import.meta.url)));}});
test('three local bundles use platform home and shared chrome with ordered actions',()=>{for(const id of ['shot-put','discus','tower-climb']){const h=read(`public/games/${id}/index.html`);assert.match(h,/href="\/"[^>]*>← 遊戲首頁/);assert.match(h,/href="\.\.\/shared\/game-ui.css"/);for(const [a,b]of [['music','restart'],['restart','pause']])assert.ok(h.indexOf(`data-game-action="${a}"`)<h.indexOf(`data-game-action="${b}"`));for(const [a,b]of [['threads','image'],['image','copy']])assert.ok(h.indexOf(`data-share="${a}"`)<h.indexOf(`data-share="${b}"`));assert.doesNotMatch(h,/workers\.dev|chatgpt\.site/);assert.match(read(`public/games/${id}/game.mjs`),/\.\.\/shared\/game-ui.mjs/);}});
test('canonical shares stay on local routes and preserve shot-put course seed',()=>{assert.match(read('public/games/shot-put/game.mjs'),/\/games\/shot-put\/\?route=/);for(const id of ['discus','tower-climb']){const s=read(`public/games/${id}/share.mjs`);assert.ok(s.includes(`/games/${id}/`));assert.doesNotMatch(s,/workers\.dev|chatgpt\.site|私人原型/);}});

import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync,existsSync} from 'node:fs';
