test('platform home, ordered toolbar, shared sheets and concise start',()=>{assert.match(html,/<a class="pf-home" href="\/" aria-label="遊戲首頁">← 遊戲首頁<\/a>/);const actions=[...html.matchAll(/data-game-action="([^"]+)"/g)].map(x=>x[1]);assert.deepEqual(actions,['music','restart','pause']);assert.ok(html.indexOf('style.css')<html.indexOf('../shared/game-ui.css'));assert.doesNotMatch(html,/私人原型/);assert.match(html,/shareFallback/);assert.match(app,/class="result-tip"/);});
