test('shared start gates keys and pause/restart freeze and clear held inputs',()=>{const h=boot();h.key('keydown','a');h.tick(60);assert.equal(h.state().phase,'ready');h.start();h.key('keydown','a');h.tick(12);h.key('keydown','k');h.tick(30);h.$('pause').onclick({isTrusted:true});const paused=JSON.stringify(h.state());h.tick(180);assert.equal(JSON.stringify(h.state()),paused);assert.equal(h.state().held.k,false);assert.equal(h.entryUI.shell.paused,true);h.entryUI.shell.continue({isTrusted:true});h.tick();assert.equal(h.state().launch,null);h.$('restart').onclick();assert.equal(h.state().phase,'ready');assert.equal(h.$('pause').disabled,false);});
test('background and pointer cancellation never throw and replay clock pauses',()=>{const h=boot();h.start();h.keys.find(n=>n.dataset.pfKey==='k').emit('pointerdown',{pointerId:7});h.tick(40);h.keys.find(n=>n.dataset.pfKey==='k').emit('pointercancel');assert.equal(h.state().held.k,false);assert.equal(h.state().launch,null);h.event('blur');assert.equal(h.entryUI.shell.paused,true);h.entryUI.shell.continue();h.eval("history=[snapshot(state),{...snapshot(state),time:1}];resultShown=true;startReplay()");h.tick(10);h.$('pause').onclick();const t=h.eval('replay.time');h.tick(90);assert.equal(h.eval('replay.time'),t);h.entryUI.shell.continue();h.tick();assert.ok(h.eval('replay.time')>t);});
