const base=new URL('../../public/games/sprint-100m/',import.meta.url);
function boot(){
 const dom=new JSDOM(readFileSync(new URL('index.html',base),'utf8'),{url:'https://preview.example/games/sprint-100m/?debug=1',runScripts:'outside-only',pretendToBeVisual:true});
 const w=dom.window,ctx=dom.getInternalVMContext();let now=0,serial=0,raf;const writes=[];w.matchMedia=()=>({matches:false,addEventListener(){},removeEventListener(){}});w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;};w.HTMLElement.prototype.setPointerCapture=function(){};w.HTMLElement.prototype.hasPointerCapture=()=>false;w.HTMLElement.prototype.releasePointerCapture=function(){};w.HTMLCanvasElement.prototype.getBoundingClientRect=()=>({width:900,height:500});w.HTMLCanvasElement.prototype.getContext=function(){return new Proxy({measureText:s=>({width:s.length*10})},{get:(target,key)=>target[key]??(()=>{})});};w.HTMLCanvasElement.prototype.toDataURL=()=>`data:image/png;base64,${++serial}`;w.HTMLCanvasElement.prototype.toBlob=function(fn){fn(new w.Blob(['test-pixels'],{type:'image/png'}));};w.URL.createObjectURL=()=>`blob:test-${++serial}`;w.URL.revokeObjectURL=()=>{};w.HTMLAnchorElement.prototype.click=function(){};
 Object.defineProperty(w,'performance',{value:{now:()=>now}});Object.assign(w,{createEntryShell,suspendHelpPresentation,syncPauseButton,...race,...replay,...runout,...camera,...records,prepared,createSprint3D:()=>null,createAudio:()=>({configure(){},unlock:()=>Promise.resolve(true),reset(){},suspend(){},resume(){},sync(){}}),requestAnimationFrame:fn=>{raf=fn;}});
