test('platform header, shared entry, input gate and concise default help',()=>{const a=boot();assert.equal(a.w.document.querySelector('.pf-home').getAttribute('href'),'/');assert.equal(a.w.document.querySelector('.pf-home').textContent,'← 遊戲首頁');assert.equal(a.read('active'),false);a.read('press(2,true);press(3,true)');a.tick(240);assert.equal(a.read('race.time'),0);assert.equal(a.read('race.phase'),'ready');assert.equal(a.w.document.querySelector('.pf-entry').open,true);a.start();assert.equal(a.read('active'),true);assert.equal(a.read('entry.active'),false);assert.equal(a.read('race.paused'),false);a.dom.window.close();});
test('pause freezes all racers and resumes without background clock jump; help returns to paused menu',()=>{const a=boot();a.start();a.read('press(2,true);press(3,true)');a.tick(220);a.read('press(2,false);press(3,false)');a.tick(20);a.click('#pause');const before=a.read('JSON.stringify(race)');a.tick(300);assert.equal(a.read('JSON.stringify(race)'),before);assert.equal(a.w.document.querySelector('[data-pf-pause]').hidden,false);a.click('[data-pf-continue]');a.tick();assert.equal(a.read('race.paused'),false);a.click('#help');assert.equal(a.read('race.paused'),true);a.click('.pf-entry-start');assert.equal(a.read('entry.active'),true);assert.equal(a.w.document.querySelector('.pf-entry').getAttribute('aria-label'),'遊戲暫停');a.click('[data-pf-continue]');assert.equal(a.read('race.paused'),false);a.dom.window.close();});
test('restart clears input, independent effect toggle remains and records back does not stack dialogs',()=>{const a=boot();a.start();a.read('press(2,true)');a.click('#pause');a.click('[data-pf-enable="effects"]');assert.equal(a.read('effectsEnabled'),false);a.click('[data-pf-restart]');assert.equal(a.read('race.runners[0].held.some(Boolean)'),false);assert.equal(a.read('effectsEnabled'),false);a.click('#pause');a.click('[data-pf-pause-ranking]');assert.equal(a.w.document.querySelector('#modal').open,true);assert.equal(a.read('entry.active'),false);a.click('#back');assert.equal(a.w.document.querySelector('#modal').open,false);assert.equal(a.read('entry.active'),true);a.click('[data-pf-continue]');assert.equal(a.w.document.querySelector('#modal').open,false);a.dom.window.close();});
test('real input completes round once, preserves frozen scene/score through replay and starts a clean second attempt',async()=>{const a=boot();a.start();a.read('press(2,true);press(3,true)');a.tick(220);a.read('press(2,false);press(3,false)');for(let i=0;i<180&&a.read('race.runners[0].finished')===null;i++){a.read(`press(${1-i%2},true);press(${1-i%2},false);press(${2+i%2},true);press(${2+i%2},false)`);a.tick(13);}assert.ok(a.read('race.runners[0].finished')>0);a.tick(500);await new Promise(r=>setImmediate(r));assert.equal(a.read('resultOpen'),true);const seconds=a.read('race.runners[0].finished'),saved=a.read('JSON.stringify(savedResult)'),photo=a.read('photo'),count=a.writes.length;assert.ok(a.w.document.querySelector('#threads').href.includes(encodeURIComponent('https://preview.example/games/sprint-100m/')));assert.ok(!a.w.document.querySelector('#threads').href.includes('debug'));assert.equal(a.w.document.activeElement.tagName,'H2');a.click('#finishReplay');a.tick(30);a.click('#pause');const time=a.read('replay.time');a.tick(180);assert.equal(a.read('replay.time'),time);a.click('#pause');a.tick(20);assert.ok(a.read('replay.time')>time);a.click('#replayBack');await new Promise(r=>setImmediate(r));assert.equal(a.read('race.runners[0].finished'),seconds);assert.equal(a.read('JSON.stringify(savedResult)'),saved);assert.equal(a.read('photo'),photo);assert.equal(a.writes.length,count);a.click('#again');assert.equal(a.read('race.runners[0].finished'),null);assert.equal(a.read('snapshot'),null);assert.equal(a.read('replay'),null);assert.equal(a.read('race.time'),0);a.dom.window.close();});
test('orientation interruption releases keys and text fields do not trigger running',()=>{const a=boot();a.start();a.read('press(2,true)');a.w.dispatchEvent(new a.w.Event('orientationchange'));assert.equal(a.read('race.paused'),true);assert.equal(a.read('race.runners[0].held.some(Boolean)'),false);a.click('[data-pf-continue]');const field=a.w.document.querySelector('#fallback-text');field.dispatchEvent(new a.w.KeyboardEvent('keydown',{key:'a',bubbles:true}));assert.equal(a.read('race.runners[0].held.some(Boolean)'),false);a.dom.window.close();});
