.pf-game .entry-help{grid-column:1/-1;text-align:left;}
.pf-game .entry-help>summary{min-height:44px;display:flex;align-items:center;font-size:14px;line-height:1.5;cursor:pointer;}
.pf-game .entry-help p{font-size:14px;line-height:1.6;display:block;}
